            return 10**9
        best = 10**9
        for px, py in s:
            d = abs(px - x) + abs(py - y)
            if d < best:
                best = d
        return best

    # frontier bias: prefer staying/advancing from cells adjacent to our territory
    def adj_to_self(x, y):
